<template>
  <div id="pagination" v-if="$store.state.dataset.items.length > 0">
    <div v-if="$store.state.dataset.totalPages <= visibleButtonNumber">
      <button
        class="btn btn-light"
        :disabled="$store.state.dataset.currentPage == i"
        @click="$store.state.dataset.currentPage = i"
        v-for="i in $store.state.dataset.totalPages" :key="i" :value="i">
        {{i}}
      </button>
    </div>
    <div v-else>
      <button 
        class="btn btn-light"
        v-if="$store.state.dataset.currentPage > visibleButtonNumber"
        @click="$store.state.dataset.currentPage = 1">
        First
      </button>
      <button 
        class="btn btn-light"
        v-if="$store.state.dataset.currentPage > visibleButtonNumber"
        @click="$store.state.dataset.currentPage--">
        ...
      </button>
      <button
        class="btn btn-light"
        :disabled="$store.state.dataset.currentPage == i"
        @click="$store.state.dataset.currentPage = i"
        v-for="i in getButtons()" :key="i" :value="i">
        {{i}}
      </button>
      <button 
        class="btn btn-light"
        v-if="$store.state.dataset.currentPage - 1 <= ($store.state.dataset.totalPages - visibleButtonNumber)"
        @click="$store.state.dataset.currentPage++">
        ...
      </button>
      <button 
        class="btn btn-light"
        v-if="$store.state.dataset.currentPage - 1 <= ($store.state.dataset.totalPages - visibleButtonNumber)"
        @click="$store.state.dataset.currentPage = $store.state.dataset.totalPages">
        Last
      </button>
    </div>
  </div>
</template>

<script>

export default {
  name: "PagiNation",
  props: ['visibleButtonNumber', 'baseUrl', 'mvvMGetter'],
  watch: {
    async '$store.state.dataset.currentPage'() {
      this.$store.state.loading = true;
      await this.$store.state.dataset.setPage(this.$store, this.baseUrl, this.mvvMGetter);
      this.$store.state.loading = false;
    }
  },
  methods: {
    getButtons() {
      let toReturn = [];
      
      let arr = [];
      let groups = [];

      for(let i = 1; i <= this.$store.state.dataset.totalPages; i++) arr.push(i);
      while (arr.length > 0) groups.push(arr.splice(0, this.visibleButtonNumber));

      let starting = groups[(this.$store.state.dataset.currentPage % this.visibleButtonNumber) == 0 ?
                            (this.$store.state.dataset.currentPage / this.visibleButtonNumber) - 1 :
                            Math.floor(this.$store.state.dataset.currentPage / this.visibleButtonNumber)][0];

      for(let i = starting; i < starting + this.visibleButtonNumber && i <= this.$store.state.dataset.totalPages; i++) {
        toReturn.push(i);
      }

      if(this.visibleButtonNumber != toReturn.length) {
        let length = toReturn.length;
        toReturn = [];
        for(let i = starting - (this.visibleButtonNumber - length); i < starting + this.visibleButtonNumber && i <= this.$store.state.dataset.totalPages; i++) {
          toReturn.push(i);
        }
      }
      
      return toReturn;
    }
  }
}
</script>